create or replace function public.listing_offers_animals(title text, description text)
returns boolean
language plpgsql
immutable
set search_path = public
as $fn$
declare
    combined text;
    about_accessory boolean;
begin
    combined := ' ' || trim(regexp_replace(
        translate(lower(coalesce(title, '') || ' ' || coalesce(description, '')),
                  'àáâäãåèéêëìíîïòóôöõùúûüñç', 'aaaaaaeeeeiiiiooooouuuunc'),
        '[^a-z0-9]+', ' ', 'g')) || ' ';
    about_accessory := combined ~ '\m(?:termoriscaldatore|transporttasche|abbigliamento|illuminazione|nebulizzatore|transportines|abbeveratoio|impermeabile|riscaldatore|transportbox|accessoires|accessories|croccantini|decorations|decorazione|decorazioni|integratore|kinderwagen|sitzstangen|thermometer|thermometre|transportin|trasportini|trasportino|accesorios|accessoire|accessorio|calentador|cappottini|cappottino|couverture|crocchette|croquettes|decoration|dekoration|fontanella|friandises|futternapf|giocattoli|giocattolo|guinzaglio|halsbander|hangematte|hygrometer|katzenbett|mangiatoia|medicinale|nourriture|passeggino|scratching|sitzstange|termometro|termostati|termostato|thermostat|tiragraffi|accesorio|accessori|accessory|antipulci|bardatura|bombillas|chauffage|cochecito|fressnapf|golosinas|guinzagli|hundebett|igrometro|katzenklo|kratzbaum|museliere|muselière|museruola|museruole|perchoirs|pettorina|pettorine|poussette|scratcher|shampoing|spielzeug|substrate|substrato|tappetino|terrarium|vestitino|vetements|acquario|ampoules|aquarium|backpack|bebedero|biscotti|bombilla|cappotto|carriers|clothing|collares|colliers|comedero|cuccetta|geschirr|granules|griffoir|halsband|juguetes|kleidung|lamparas|leckerli|lettiera|lettiere|maglione|mantella|maulkorb|perchoir|posatoio|pullover|raincoat|rascador|rucksack|scaletta|semillas|spazzola|spazzole|strahler|striscia|stroller|substrat|sustrato|terrario|training|trespoli|trespolo|truciolo|vetement|vivarium|acquari|acuario|ampoule|arenero|blanket|carrier|casetta|cepillo|cestino|ciotola|ciotole|clothes|collare|collari|collars|collier|coussin|cuscini|cuscino|cushion|faretti|faretto|fiocchi|gamelle|graines|gravier|hammock|harnais|harness|heatmat|heizung|juguete|knochen|lampada|lampade|lampara|laufrad|lettino|leuchte|litiere|mangime|manteau|mochila|pallina|palline|paniers|pellets|peluche|perchas|perches|playpen|recinti|recinto|scatola|scratch|sellino|shampoo|sweater|vestito|voliera|voliere|zubehor|abrigo|amache|bridle|brosse|burste|caisse